#!/usr/bin/env python3
import re
p="index.html"
html=open(p,encoding="utf-8").read()
def block_span(html,id_attr,tag="div"):
    m=re.search(r'(<%s[^>]*id="%s"[^>]*>)'%(tag,re.escape(id_attr)),html)
    if not m: raise SystemExit(f"not found {id_attr}")
    start=m.end(); depth=1; pat=re.compile(r'</?%s\b[^>]*>'%tag)
    for mm in pat.finditer(html,start):
        if mm.group(0).startswith('</'):
            depth-=1
            if depth==0: return start,mm.start()
        elif not mm.group(0).endswith('/>'): depth+=1
    raise SystemExit("unbalanced")
def replace_block(html,id_attr,new_inner,tag="div"):
    s,e=block_span(html,id_attr,tag); return html[:s]+new_inner+html[e:]
def sub(pattern,repl,html,flags=0,label=""):
    new,n=re.subn(pattern,repl,html,count=1,flags=flags)
    if n==0: raise SystemExit(f"pattern not found: {label or pattern[:90]}")
    return new

html=sub(r'<!-- EDITION:NAME -->.*?<!-- /EDITION:NAME -->','<!-- EDITION:NAME --> Evening Edition — published 5:30 PM PT <!-- /EDITION:NAME -->',html,flags=re.S,label="edition")
html=sub(r'<!-- WEATHER:BUG -->.*?<!-- /WEATHER:BUG -->','<!-- WEATHER:BUG --> ⛓️ SR-88 chain control cleared off both boards; new traffic hazard SR-104 / Michigan Bar Rd; partly cloudy tonight, low 41°; SR-49 no restrictions; no NWS alert (CHP / Caltrans / NWS) <!-- /WEATHER:BUG -->',html,flags=re.S,label="bug")
html=sub(r'<!-- LEAD:HEADLINE -->.*?<!-- /LEAD:HEADLINE -->','<!-- LEAD:HEADLINE --> Evening in the foothills — SR-88&#8217;s chain control has cleared off both boards, a new hazard is logged on SR-104 at Michigan Bar Rd, and the Jackson City Council meets at 6:30 PM <!-- /LEAD:HEADLINE -->',html,flags=re.S,label="headline")
html=sub(r'<p><!-- LEAD:BODY -->.*?</p>','<p><!-- LEAD:BODY --> Evening finds the foothills quieting under a partly cloudy sky, <b>low near 41 tonight</b> after a mostly sunny day that topped out near 54. The day&#8217;s road story has resolved: <b>SR-88&#8217;s chain control is gone from the CHP board at the evening read (5:27 PM)</b> — the Kirkwood Meadows Dr entry that stood in the log since 5:46 AM no longer appears — and <b>Caltrans&#8217; 5:26 PM report lists no chain control either</b>, so the two sources agree again: no chain control on SR-88 tonight. The morning&#8217;s Ellis Rd hazard stayed cleared. One new item is on the board: a <b>traffic hazard on SR-104 at Michigan Bar Rd</b>, logged 5:07 PM, westbound just west of the junction (see the Safety Wire). Caltrans&#8217; tree work on <b>SR-88 near the SR-124 junction</b> wrapped for today at 5:00 PM and returns Tuesday, 8:00 AM–5:00 PM. <b>No National Weather Service alert is in effect</b> for the Fiddletown point. <b>SR-49 and SR-124 report no restrictions.</b> Of today&#8217;s three database listings, the <b>Sierra Oak Farms veggie stand</b> sells on at Fiddletown Rd and Mt. Whitney — <b>Tuesday is its last day</b> — Ione&#8217;s Preschool Story Time ran this morning, and the <b>Jackson City Council meets at City Hall at 6:30 PM</b>, the evening&#8217;s remaining business. Tomorrow the Rotary Club packs Thanksgiving boxes in Plymouth at 8:00 AM, and Tuesday night brings only a chance of rain (about 30%) — Wednesday and Thanksgiving Day read mostly sunny. <!-- /LEAD:BODY --></p>',html,flags=re.S,label="lead body")

safety='''
    <div class="item"><p><b>Cleared — SR-88 chain control is off both boards.</b> The <b>chain-control entry at SR-88 / Kirkwood Meadows Dr</b> that stood in the CHP log from 5:46 AM through the midday read <b>no longer appears on the CHP Stockton board at the evening read (updated 5:27 PM)</b>, and <b>Caltrans&#8217; 5:26 PM SR-88 report lists no chain-control segment</b> — the two sources agree again, and the desk retires the item: <b>no chain control on SR-88 tonight</b>. No closure was reported on SR-88 at any point today.</p><p class="meta">Sources: <a href="https://cad.chp.ca.gov/Traffic.aspx">CHP CAD Traffic — Stockton center</a>, read 5:27 PM PT, Nov 23 · Caltrans SR-88 road report, 5:26 PM PT, Nov 23</p></div>
    <div class="item"><p><b>New — traffic hazard on SR-104 at Michigan Bar Rd.</b> CHP logged a <b>traffic hazard at <a href="https://maps.apple.com/?ll=38.3793,-120.98618&amp;q=SR-104%20%2F%20Michigan%20Bar%20Rd">SR-104 / Michigan Bar Rd</a></b> at <b>5:07 PM</b> — westbound, just west of the junction, in the Amador area west of Ione. No further detail is on the board; drivers on the Ione–Rancho Murieta run should expect something in or near the westbound side and pass with care.</p><p class="meta">Source: <a href="https://cad.chp.ca.gov/Traffic.aspx">CHP CAD Traffic — Stockton center</a>, read 5:27 PM PT, Nov 23</p></div>
    <div class="item"><p><b>Tree work — SR-88 near SR-124 wrapped for today; back Tuesday.</b> Caltrans&#8217; evening report carries <b>one-way controlled traffic at various locations from 0.8 miles west of the junction of SR-124 to the junction of SR-124 (Amador Co), 8:00 AM to 5:00 PM through Tuesday, Nov 24, due to tree work</b> — today&#8217;s window has closed; expect brief holds again Tuesday. The same report lists one-way controlled traffic at <b>McFadden Street in Pine Grove on Tuesday, Nov 24, 8:00 AM to 5:00 PM</b>, also for tree work.</p><p class="meta">Source: Caltrans SR-88 road report, 5:26 PM PT, Nov 23</p></div>
    <div class="item"><p><b>Weather — no alert in effect; a partly cloudy night, and the week&#8217;s rain stays light.</b> At the evening check (5:25 PM), the National Weather Service alert feed carries <b>no watch, warning, or advisory for the Fiddletown point</b>. <b>Tonight:</b> partly cloudy, low near 41, temperatures rising to about 43 overnight. <b>Tuesday:</b> partly sunny, high near 59; <b>Tuesday night</b> brings only a chance of rain (about 30%), and <b>Wednesday</b> reads mostly sunny, high near 62 — Thanksgiving Day stays mostly sunny, high near 61. No weather event ran today; there are no storm totals to close out.</p><p class="meta">Source: National Weather Service Sacramento — alerts &amp; forecast for the Fiddletown point, checked 5:25 PM PT, Nov 23</p></div>
    <div class="item"><p><b>Roads — SR-49 and SR-124 report no restrictions; the rest of the board sits outside the beat.</b> Caltrans&#8217; evening reports list <b>no traffic restrictions on SR-49 or SR-124</b>. The CHP board at 5:27 PM held seven incidents; apart from the SR-104 hazard above, the nearest is a <b>collision with no injuries on SR-4 at Rock Creek Rd (San Andreas area), logged 4:48 PM</b> — outside the paper&#8217;s beat, noted for drivers headed that way. Nothing else names Fiddletown, Plymouth, Jackson, Sutter Creek, Ione, Drytown, Volcano, or Pine Grove.</p><p class="meta">Sources: Caltrans SR-49 &amp; SR-124 road reports, 5:26 PM PT, Nov 23 · <a href="https://cad.chp.ca.gov/Traffic.aspx">CHP CAD Traffic — Stockton center</a>, read 5:27 PM PT, Nov 23</p></div>
    <div class="item"><p><b>Fire — quiet in the foothills at the evening check.</b> No fire incident in the beat appears on the CHP board this evening. Burn-day status: the paper does not state it — the recorded Burn Day Line (updated daily 4–5 PM) is the authority; call before lighting any outdoor fire (see the Burn Day Line in the rail).</p><p class="meta">Source: CHP CAD Traffic — Stockton center, read 5:27 PM PT, Nov 23</p></div>
  '''
html=replace_block(html,"safety-wire",safety)

s,e=block_span(html,"today-events"); blk=html[s:e]
blk2,n=re.subn(r'<p><b>Midday on a quiet Monday — one listing still ahead\.</b>.*?</p>','<p><b>Evening on a quiet Monday — the council is tonight&#8217;s remaining business.</b> Today in the Foothills is built only from the events database&#8217;s published feed, the same feed the public events viewer reads — <b>three in-beat events span today</b>, listed below as cards, verified against the feed this evening and unchanged from the midday edition. The <b>Sierra Oak Farms veggie stand</b> (featured first, at Dave&#8217;s direction) sells on at Fiddletown Rd and Mt. Whitney — <b>Tuesday, Nov 24 is its last day</b>; <b>Preschool Story Time at the Ione Branch Library has run</b> (10:00 AM); and the <b>Jackson City Council meets at City Hall at 6:30 PM</b>. The desk&#8217;s evening discovery sweep (LodeDown&#8217;s Amador listings, Amador Wine Country) found nothing in the beat for today that is not already in the database — LodeDown&#8217;s Monday Amador lines are the same story time and council meeting. <b>Tomorrow, Tue Nov 24, in the database:</b> the Rotary Club packs Thanksgiving boxes at the Spur Emporium building, Amador County Fairgrounds, Plymouth, 8:00 AM, and Baked in Amador&#8217;s Thanksgiving preorder pickup runs 11:00 AM–3:00 PM in Volcano (orders closed Sun Nov 22 — see The Week Ahead).</p>',blk,count=1,flags=re.S)
if n==0: raise SystemExit("today intro not found")
html=html[:s]+blk2+html[e:]

html=sub(r'<div class="item"><p><b>Today, Mon Nov 23 — the rest of the day:</b>.*?</div>','<div class="item"><p><b>Today, Mon Nov 23 — this evening:</b> <b>Jackson City Council</b>, Jackson City Hall, 6:30 PM, free and open to the public · the <b>Sierra Oak Farms veggie stand</b> sells on at Fiddletown Rd and Mt. Whitney, last day Tuesday (Ione&#8217;s Preschool Story Time ran this morning — see Today in the Foothills for the cards).</p><p class="meta">Source: <a href="https://events.fiddletowngazette.com/">events database</a> published feed · Checked Nov 23</p></div>',html,flags=re.S,label="week today")

weather='''
    <p><b>A fair Monday evening, and the week&#8217;s wet stretch stays light.</b> <b>Tonight:</b> partly cloudy, low near 41, with temperatures rising to about 43 overnight. <b>Tuesday:</b> partly sunny, high near 59; <b>Tuesday night</b> brings only a chance of rain (about 30%), low near 49, and <b>Wednesday</b> reads mostly sunny, high near 62. <b>Thanksgiving Day:</b> mostly sunny, high near 61. On the roads, SR-88&#8217;s chain control has cleared off both boards; a new hazard is logged on SR-104 at Michigan Bar Rd (see the Safety Wire). The five-day panel above carries the numbers, and every day in it opens its own hour-by-hour page.</p>
    <p class="meta">Source: National Weather Service, Sacramento (Fiddletown point) · Forecast checked 5:28 PM PT, Nov 23</p>
  '''
html=replace_block(html,"weather",weather)

html=sub(r'The desk re-checked the home crossing at midday — <b>SR-88&#8217;s chain control still stands in the CHP CAD log at Kirkwood Meadows Dr</b> \(board updated 12:31 PM today\), on the approach to Carson Pass; Caltrans&#8217; 12:30 PM web report lists no chain-control segment, and the desk carries the CHP log as governing\.','The desk re-checked the home crossing this evening — <b>SR-88&#8217;s chain control has cleared</b>: the Kirkwood Meadows Dr entry is gone from the CHP CAD board (updated 5:27 PM today) and Caltrans&#8217; 5:26 PM web report lists no chain-control segment, on the approach to Carson Pass.',html,label="passes")

html=sub(r'Viewing note \(honest, morning check\):.*?Dress warm; the ridge cools fast after sunset\.','Viewing note (honest, evening check): tonight is <b>partly cloudy, low near 41</b> — no fog in the forecast, a kinder night than Sunday&#8217;s. The evening&#8217;s actual sky matches the forecast so far: a genuinely good night for <b>Saturn and the big Moon</b> — the Moon&#8217;s glare is the only spoiler, washing out faint stars and meteors. Dress warm; the ridge cools fast after sunset.',html,flags=re.S,label="star note")

